def is_cjk(char):
    code = ord(char)
    return 0x4E00 <= code <= 0x9FFF


def draw_char(device, char, x, y, color=1):
    rows = GLYPHS.get(char)

    if rows is None:
        return False

    for yy, mask in enumerate(rows):
        for xx in range(CELL_W):
            if mask & (1 << xx):
                device.pixel(
                    int(x) + xx,
                    int(y) + yy,
                    int(color),
                )

    return True
